g-block:75px;border-top:1px solid var(--line)}.section-head{display:flex;justify-content:space-between;align-items:end;gap:70px;margin-bottom:28px}.section-head h2{margin-bottom:0}.section-head>p{max-width:330px;font-size:13px;color:var(--muted);margin-bottom:0}.grid{display:grid;gap:22px}.three{grid-template-columns:repeat(3,1fr)}.course{padding:28px;border:1px solid var(--line);border-radius:var(--radius);background:white;display:flex;flex-direction:column}.course:nth-child(2){background:#e9eddf}.course p,.approach-grid p,.steps-grid p{font-size:14px;color:var(--muted)}.course-bottom{border-top:1px solid #d0d6c7;padding-top:22px;margin-top:auto;display:flex;align-items:center;gap:15px}.course-bottom small{font-size:11px}.round-link{display:grid;place-items:center;border:1px solid var(--ink);min-width:38px;height:38px;border-radius:50%;font-size:23px;margin-left:auto}.round-link:hover{background:var(--lime)}.dark-section{background:var(--ink);color:var(--paper)}.dark-section .section{border:0}.dark-section .eyebrow{color:var(--lime)}.approach-grid{margin-top:45px;gap:50px}.approach-grid article{border-top:1px solid #4a6058;padding-top:26px}.approach-grid p{color:#c6d0c7}.step-num{font-size:13px;font-weight:700;display:inline-block;margin-bottom:22px}.dark-section .step-num{color:var(--lime)}.team-section{display:grid;grid-template-columns:1fr 1fr;gap:70px;align-items:center}.teacher{background:#e9eddf;border-radius:var(--radius);display:flex;overflow:hidden;min-height:260px}.portrait{width:40%;min-width:130px;background:#cbd9bc;position:relative;overflow:hidden}.head{background:#94ad81;width:66px;height:75px;border-radius:40px;position:absolute;top:60px;left:50%;transform:translateX(-50%)}.shoulders{background:#94ad81;width:180px;height:145px;position:absolute;top:145px;left:50%;transform:translateX(-50%);border-radius:100px 100px 0 0}.portrait span{position:absolute;bottom:14px;left:0;width:100%;text-align:center;font-size:9px;letter-spacing:.1em}.teacher-copy{pad